import json
import os
import time
from functools import wraps
from pathlib import Path
from flask import Flask, jsonify, request

BASE_DIR = Path('/workspace')
DATA_DIR = BASE_DIR / 'data'
STATE_FILE = DATA_DIR / 'sprat_state.json'

DEFAULT_STATE = {
    'users': [
        {'username': 'admin', 'role': 'administrator'},
        {'username': 'manager', 'role': 'project_manager'},
        {'username': 'analyst', 'role': 'analyst'},
        {'username': 'guest', 'role': 'guest'},
    ],
    'projects': [
        {
            'id': 1,
            'name': 'Sample Project',
            'status': 'active',
            'items': [
                {'id': 1, 'type': 'goal', 'title': 'Protect user data', 'policy': 'Privacy Policy A', 'status': 'draft', 'last_modified_by': 'analyst', 'updated_at': time.time(), 'source': 'imported', 'trace_links': [1]},
                {'id': 2, 'type': 'policy', 'title': 'Privacy Policy A', 'status': 'approved', 'last_modified_by': 'manager', 'updated_at': time.time(), 'source': 'manual', 'trace_links': []},
            ],
            'conflicts': [],
            'imports': [],
            'glossary': {
                'requirement': {'definition': 'A statement of needed system behavior.'},
                'policy': {'definition': 'A governing rule or principle.'}
            }
        }
    ],
    'audit_log': []
}


def load_state():
    DATA_DIR.mkdir(exist_ok=True)
    if STATE_FILE.exists():
        return json.loads(STATE_FILE.read_text())
    return DEFAULT_STATE


def save_state(state):
    DATA_DIR.mkdir(exist_ok=True)
    STATE_FILE.write_text(json.dumps(state, indent=2))


def role_required(*allowed):
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            username = request.headers.get('X-User', 'guest')
            state = request.app_state
            user = next((u for u in state['users'] if u['username'] == username), None)
            if not user:
                user = {'username': username, 'role': 'guest'}
            request.user = user
            if user['role'] not in allowed:
                return jsonify({'error': 'forbidden', 'message': 'Role not permitted for this action.'}), 403
            return fn(*args, **kwargs)
        return wrapper
    return decorator


def create_app():
    app = Flask(__name__)
    state = load_state()

    @app.before_request
    def inject_state():
        request.app_state = state

    @app.get('/')
    def index():
        return jsonify({
            'name': 'SPRAT',
            'description': 'Security and Privacy Requirements Analysis Tool',
            'projects': len(state['projects']),
            'roles': ['administrator', 'project_manager', 'analyst', 'guest']
        })

    @app.get('/dashboard')
    def dashboard():
        project = state['projects'][0]
        unresolved = [i for i in project['items'] if i.get('status') in ('needs review', 'conflicting mapping', 'unresolved import')]
        return jsonify({'project': project['name'], 'recent_items': project['items'][-5:], 'unresolved': unresolved, 'audit_log_entries': len(state['audit_log'])})

    @app.get('/search')
    def search():
        q = request.args.get('q', '').lower()
        matches = []
        for project in state['projects']:
            for item in project['items']:
                text = json.dumps(item).lower()
                if q in text:
                    matches.append({'project_id': project['id'], 'item': item})
        return jsonify({'query': q, 'matches': matches})

    @app.post('/projects/<int:project_id>/items')
    @role_required('administrator', 'project_manager', 'analyst')
    def create_item(project_id):
        payload = request.get_json(force=True)
        project = next((p for p in state['projects'] if p['id'] == project_id), None)
        if not project:
            return jsonify({'error': 'not_found'}), 404
        new_id = max([i['id'] for i in project['items']] + [0]) + 1
        item = {
            'id': new_id,
            'type': payload.get('type', 'requirement'),
            'title': payload.get('title', 'Untitled'),
            'status': payload.get('status', 'draft'),
            'policy': payload.get('policy'),
            'source': payload.get('source', 'manual'),
            'trace_links': payload.get('trace_links', []),
            'last_modified_by': request.user['username'],
            'updated_at': time.time(),
            'rationale': payload.get('rationale'),
            'notes': payload.get('notes'),
            'assumptions': payload.get('assumptions'),
        }
        project['items'].append(item)
        state['audit_log'].append({'action': 'create_item', 'user': request.user['username'], 'project_id': project_id, 'item_id': new_id, 'ts': time.time()})
        save_state(state)
        return jsonify(item), 201

    @app.post('/projects/<int:project_id>/conflicts')
    @role_required('administrator', 'project_manager', 'analyst')
    def add_conflict(project_id):
        payload = request.get_json(force=True)
        project = next((p for p in state['projects'] if p['id'] == project_id), None)
        if not project:
            return jsonify({'error': 'not_found'}), 404
        conflict = {
            'id': len(project['conflicts']) + 1,
            'item_id': payload.get('item_id'),
            'status': 'needs review',
            'details': payload.get('details', ''),
            'comments': []
        }
        project['conflicts'].append(conflict)
        save_state(state)
        return jsonify(conflict), 201

    @app.post('/projects/<int:project_id>/imports')
    @role_required('administrator', 'project_manager', 'analyst')
    def import_items(project_id):
        payload = request.get_json(force=True)
        project = next((p for p in state['projects'] if p['id'] == project_id), None)
        if not project:
            return jsonify({'error': 'not_found'}), 404
        staging = []
        for raw in payload.get('items', []):
            mapped = raw.copy()
            mapped['import_status'] = 'review_required' if raw.get('ambiguous') else 'staged'
            staging.append(mapped)
        project['imports'].append({'created_by': request.user['username'], 'staging': staging, 'published': False})
        save_state(state)
        return jsonify({'staged_count': len(staging), 'review_queue': [i for i in staging if i['import_status'] == 'review_required']}), 202

    @app.get('/projects/<int:project_id>/glossary/<term>')
    def glossary_lookup(project_id, term):
        project = next((p for p in state['projects'] if p['id'] == project_id), None)
        if not project:
            return jsonify({'error': 'not_found'}), 404
        definition = project['glossary'].get(term.lower())
        if definition:
            return jsonify({'term': term, 'accepted_definition': definition['definition'], 'context': 'approved glossary term'})
        warnings = []
        if any(term.lower() in existing for existing in project['glossary']):
            warnings.append('possible duplicate or near match')
        return jsonify({'term': term, 'warnings': warnings, 'suggestions': list(project['glossary'].keys())})

    return app
EOF

